    private AttractionCategory resolveCategory(Map<String, AttractionCategory> catMap, String catName) {
        if (catName != null && catMap.containsKey(catName)) {
            return catMap.get(catName);
        }
        if (catName != null) {
            String lower = catName.toLowerCase();
            if (lower.contains("education") || lower.contains("university") || lower.contains("college")) return catMap.getOrDefault("Education / University", catMap.get("Culture"));
            if (lower.contains("park") || lower.contains("garden")) return catMap.getOrDefault("Parks and Gardens", catMap.get("Parks"));
            if (lower.contains("temple") || lower.contains("religious") || lower.contains("spiritual")) return catMap.get("Temples and Religious Places");
            if (lower.contains("fort") || lower.contains("palace")) return catMap.get("Forts and Palaces");
            if (lower.contains("beach")) return catMap.get("Beaches");
            if (lower.contains("waterfall")) return catMap.get("Waterfalls");
            if (lower.contains("lake")) return catMap.get("Lakes");
            if (lower.contains("museum")) return catMap.get("Museums");
            if (lower.contains("history") || lower.contains("historic")) return catMap.get("Historical Places");
            if (lower.contains("culture")) return catMap.get("Culture");
        }
        return catMap.getOrDefault("Historical Places", catMap.values().iterator().next());
    }

    private City getOrCreateCity(State state, String name, Double lat, Double lon, String desc) {
        return cityRepository.findByNameIgnoreCase(name).orElseGet(() -> {
            City c = new City(state, name, lat, lon, desc, true);
            return cityRepository.save(c);
        });
    }

    private void getOrCreateDestination(City city, String name, String stateName, String heroImage, String bestSeason, Double cost) {
        if (destinationRepository.findByNameIgnoreCase(name).isEmpty()) {
            Destination d = new Destination();
            d.setCity(city);
            d.setName(name);
            d.setStateName(stateName);
            d.setDescription(city != null ? city.getDescription() : name);
            d.setHeroImage(heroImage);
            d.setBestSeason(bestSeason);
            d.setAvgDailyCostInr(cost);
            d.setRating(4.8);
            d.setFeatured(true);
            destinationRepository.save(d);
        }
    }

    private void addAttraction(
            @NonNull City city, 
            AttractionCategory category, 
            @NonNull String name, 
            String subcategory, 
            String description, 
            Double lat, 
            Double lon, 
            String indoorOutdoor, 
            String intensity, 
            String ageSuitability, 
            String open, 
            String close, 
            Double duration, 
            Double fee, 
            Double rating, 
            Integer reviews, 
            String tags) {
        if (attractionRepository.findByNameIgnoreCase(name).isPresent()) {
            return;
        }
        Attraction a = new Attraction();
        a.setCity(city);
        a.setCategory(category);
        a.setName(name);
        a.setSubcategory(subcategory);
        a.setDescription(description);
        a.setLatitude(lat);
        a.setLongitude(lon);
        a.setIndoorOutdoor(indoorOutdoor);
        a.setActivityIntensity(intensity);
        a.setAgeSuitability(ageSuitability);
        a.setOpeningTime(open);
        a.setClosingTime(close);
        a.setDurationHours(duration);
        a.setEntryFeeInr(fee);
        a.setRating(rating);
        a.setReviewsCount(reviews);
        a.setTags(tags);
        a.setIsAvailable(true);
        a.setFeatured(true);
        attractionRepository.save(a);
    }
